// The original clinical-case dataset is language-major (RU/EN/KZ arrays of
// answer options), while the examination renderer expects answer-major
// arrays (one RU/EN/KZ tuple per answer). Normalize before mixing datasets.
export function normalizeClinicalCase(item){
  if(!Array.isArray(item.options) || item.options.length !== 3 ||
     !item.options.every(row=>Array.isArray(row) && row.length === 4)){
    throw new Error(`Invalid clinical-case options for module ${item.module}`);
  }
  return {...item, options:Array.from({length:4},(_,i)=>
    [item.options[0][i],item.options[1][i],item.options[2][i]])};
}
items.push(...reasoningExamItems, ...expandedBank, ...caseBasedItems.map(normalizeClinicalCase), ...integratedExamItems);
