export function examCenter(L){const options=modules.map(m=>`<option value="${m.id}">${m.id}. ${safe(m.title[L])}</option>`).join('');return `<section class="experiment exam-center"><h2>${T(L,'Самостоятельный экзаменационный центр','Independent examination center','Жеке емтихан орталығы')}</h2><p>${T(L,'Отдельно от 25 учебных разделов. Выберите экзамен по модулю или итоговую проверку всего курса.','Separate from the 25 learning modules. Choose a module exam or a comprehensive exam.','25 оқу бөлімінен бөлек. Модуль емтиханын немесе қорытынды емтиханды таңдаңыз.')}</p><div class="exam-controls"><label>${T(L,'Охват','Scope','Қамту')}<select id="exam-scope"><option value="all">${T(L,'Итоговый экзамен — весь курс','Final exam — entire course','Қорытынды емтихан — толық курс')}</option>${options}</select></label><label>${T(L,'Режим','Mode','Режим')}<select id="exam-mode"><option value="practice">${T(L,'Тренировка','Practice','Жаттығу')}</option><option value="formal">${T(L,'Экзамен с таймером','Timed examination','Уақытпен емтихан')}</option></select></label><button class="button" type="button" id="exam-start">${T(L,'Начать попытку','Start attempt','Тапсырманы бастау')}</button></div><div id="exam-status" role="status"></div><div id="exam-area"></div><div id="exam-feedback" aria-live="polite"></div><p class="source-line">${T(L,'Учебный банк: ','Teaching bank: ','Оқу қоры: ')+items.length+T(L,' уникальных заданий по 25 модулям. Часть вопросов — варианты расчётных семейств. В попытке до 20 или 50 вопросов; экзамен длится 25 или 60 минут.',' unique items across 25 modules. Some items are variants of calculation families. Up to 20 or 50 questions per attempt; timed exams allow 25 or 60 minutes.',' бірегей тапсырма, 25 модуль. Кейбір тапсырмалар — есептік топтардың нұсқалары. Бір әрекетте 20-ға дейін немесе 50 сұрақ; уақыт 25 немесе 60 минут.')} </p></section>`;}
export function initExamCenter(L){const start=document.querySelector('#exam-start');if(!start)return;const storageKey='respiratory-exam-attempt-v1';const readSaved=()=>{try{return validateExamAttempt(JSON.parse(localStorage.getItem(storageKey)||'null'),items);}catch{return null;}};const resume=document.createElement('button');resume.type='button';resume.id='exam-resume';let resumeRequested=false;const updateResume=()=>{const pending=readSaved();resume.disabled=!pending;resume.textContent=pending?.finished?T(L,'Просмотреть завершённую попытку','View completed attempt','Аяқталған әрекетті қарау'):T(L,'Продолжить сохранённую попытку','Resume saved attempt','Сақталған әрекетті жалғастыру');};start.after(resume);updateResume();resume.onclick=()=>{const pending=readSaved();if(!pending)return;document.querySelector('#exam-scope').value=pending.scope;document.querySelector('#exam-mode').value=pending.mode;resumeRequested=true;start.click();};start.addEventListener('click',()=>{const saved=resumeRequested?readSaved():null;resumeRequested=false;clearAttemptListeners();if(timer){clearInterval(timer);timer=null;}const scope=document.querySelector('#exam-scope').value;const mode=document.querySelector('#exam-mode').value;const pool=scope==='all'?items:items.filter(x=>String(x.module)===scope);const count=scope==='all'?50:20;const selected=saved?saved.selected.map(index=>items[index]):diverseSample(pool,count,scope==='all');const area=document.querySelector('#exam-area');const feedback=document.querySelector('#exam-feedback');feedback.innerHTML='';if(!selected.length){area.textContent=T(L,'Для выбранного раздела вопросы пока отсутствуют.','No questions are available for this module.','Бұл бөлімде сұрақтар әзірше жоқ.');return;}let remaining=scope==='all'?60*60:25*60;if(saved?.mode==='formal')remaining=Math.max(0,Math.ceil((saved.deadline-Date.now())/1000));const status=document.querySelector('#exam-status');const renderClock=()=>{status.textContent=mode==='formal'?T(L,'Осталось: ','Time left: ','Қалған уақыт: ')+`${Math.floor(remaining/60)}:${String(remaining%60).padStart(2,'0')}`:T(L,'Тренировочный режим','Practice mode','Жаттығу режимі')};renderClock();const shown=selected.map((item,index)=>({...item,choices:saved?saved.orders[index].map(i=>({texts:item.options[i],idx:i})):shuffle(item.options.map((texts,i)=>({texts,idx:i})))}));area.innerHTML=`<form id="exam-form">${shown.map((item,i)=>`<fieldset class="exam-question"><legend>${i+1}. ${safe(item.q[L])}</legend>${item.choices.map(c=>`<label><input type="radio" name="q${i}" value="${c.idx}"> ${safe(c.texts[L])}</label>`).join('')}</fieldset>`).join('')}<button class="button" type="submit">${T(L,'Завершить и оценить','Submit and grade','Аяқтау және бағалау')}</button></form>`;const form=area.querySelector('form');const deadline=mode==='formal'?(saved?.deadline??Date.now()+remaining*1000):null;
 const readAnswers=()=>shown.map((_,i)=>{const v=form.querySelector(`input[name="q${i}"]:checked`);return v?Number(v.value):null;});
 const restoreAnswers=values=>{shown.forEach((_,i)=>form.querySelectorAll(`input[name="q${i}"]`).forEach(input=>input.checked=values[i]!==null&&Number(input.value)===values[i]));};
 if(saved)restoreAnswers(saved.answers);let acceptedAnswers=readAnswers();
 const navigation=document.createElement('div');navigation.className='exam-attempt-navigation';navigation.innerHTML=`<p>${T(L,'Ответы сохраняются в этом браузере; при возвращении используйте кнопку продолжения.','Answers are saved in this browser; use Resume when you return.','Жауаптар осы браузерде сақталады; қайтқанда жалғастыру батырмасын қолданыңыз.')}</p><button type="button" data-exam-unanswered>${T(L,'К первому неотвеченному','First unanswered question','Алғашқы жауапсыз сұраққа')}</button><span data-exam-count role="status"></span>`;form.before(navigation);
 const updateNavigation=()=>{const missing=readAnswers().filter(x=>x===null).length;navigation.querySelector('[data-exam-count]').textContent=' '+T(L,'Без ответа: ','Unanswered: ','Жауапсыз: ')+missing;};
 navigation.querySelector('button').onclick=()=>{const index=readAnswers().findIndex(x=>x===null);if(index<0)return;const field=form.querySelectorAll('fieldset')[index];field.tabIndex=-1;field.focus();field.scrollIntoView({block:'center'});};
 const persist=(finished=false,expired=false)=>{updateNavigation();try{localStorage.setItem(storageKey,JSON.stringify({version:1,bank:examBankSignature(items),scope,mode,deadline,selected:selected.map(item=>items.indexOf(item)),orders:shown.map(item=>item.choices.map(c=>c.idx)),answers:readAnswers(),finished,expired}));updateResume();}catch{navigation.querySelector('[data-exam-count]').textContent+=' · '+T(L,'Сохранить попытку не удалось','Could not save attempt','Әрекетті сақтау мүмкін болмады');}};
 persist();form.addEventListener('change',()=>{if(form.dataset.finished==='yes')return;acceptedAnswers=readAnswers();persist();});const finish=(expired=false)=>{if(deadline!==null && Date.now()>=deadline)expired=true;if(form.dataset.finished==='yes')return;form.dataset.finished='yes';persist(true,expired);navigation.querySelector('button').disabled=true;clearAttemptListeners();if(timer){clearInterval(timer);timer=null;}const data=new FormData(form);let score=0;let unanswered=0;const moduleStats=new Map();const lines=shown.map((item,i)=>{const answer=data.get('q'+i);const ok=answer!==null&&Number(answer)===item.answer;if(ok)score++;if(answer===null)unanswered++;const stat=moduleStats.get(item.module)||{correct:0,total:0,unanswered:0};stat.total++;if(ok)stat.correct++;if(answer===null)stat.unanswered++;moduleStats.set(item.module,stat);const chosen=answer===null?T(L,'Нет ответа','No answer','Жауап берілмеген'):item.options[Number(answer)]?.[L]??T(L,'Неизвестный вариант','Unknown option','Белгісіз нұсқа');return `<li><strong>${ok?'✓':'✗'}</strong> ${safe(item.q[L])}<p>${T(L,'Ваш ответ: ','Your answer: ','Сіздің жауабыңыз: ')}${safe(chosen)}</p><p>${T(L,'Правильный ответ: ','Correct answer: ','Дұрыс жауап: ')}${safe(item.options[item.answer][L])}. ${safe(item.explain[L])}</p></li>`;});const breakdown=[...moduleStats].sort((a,b)=>a[0]-b[0]).map(([id,stat])=>`<li>${safe(modules.find(m=>m.id===id)?.title[L]||String(id))}: ${stat.correct}/${stat.total}</li>`).join('');form.querySelectorAll('input,button').forEach(el=>el.disabled=true);feedback.innerHTML=`<h3>${expired?T(L,'Время истекло. ','Time expired. ','Уақыт бітті. '):''}${T(L,'Результат','Result','Нәтиже')}: ${score}/${shown.length} (${Math.round(100*score/shown.length)}%) · ${T(L,'Без ответа: ','Unanswered: ','Жауапсыз: ')}${unanswered}</h3><h4>${T(L,'Результаты по разделам','Results by module','Бөлімдер бойынша нәтижелер')}</h4><ul>${breakdown}</ul><h4>${T(L,'Разбор ответов','Answer review','Жауаптарды талдау')}</h4><ol>${lines.join('')}</ol>`;feedback.setAttribute('tabindex','-1');feedback.focus({preventScroll:true});feedback.scrollIntoView({behavior:'smooth',block:'start'});};form.addEventListener('submit',e=>{e.preventDefault();finish();});
if(mode==='formal'){
  // A suspended background tab may not run setInterval at the deadline.
  // Recheck before accepting a new answer and when the tab becomes active.
  const verifyDeadline=()=>{
    if(form.dataset.finished==='yes')return;
    remaining=Math.max(0,Math.ceil((deadline-Date.now())/1000));
    renderClock();
    if(Date.now()>=deadline)finish(true);
  };
  const onVisibility=()=>{if(!document.hidden)verifyDeadline();};
  const onFocus=()=>verifyDeadline();
  const onInput=()=>{if(Date.now()>=deadline)restoreAnswers(acceptedAnswers);else{acceptedAnswers=readAnswers();persist();}verifyDeadline();};
  document.addEventListener('visibilitychange',onVisibility);
  window.addEventListener('focus',onFocus);
  form.addEventListener('input',onInput,true);
  clearAttemptListeners=()=>{
    document.removeEventListener('visibilitychange',onVisibility);
    window.removeEventListener('focus',onFocus);
    form.removeEventListener('input',onInput,true);
    clearAttemptListeners=()=>{};
  };
  timer=setInterval(verifyDeadline,1000);
}else{clearAttemptListeners=()=>{};}
if(saved?.finished)finish(Boolean(saved.expired));else if(deadline!==null&&Date.now()>=deadline)finish(true);
});}
